<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';$user=requireUser($pdo);
if($_SERVER['REQUEST_METHOD']==='POST'){$d=input();$content=sanitizeRichText((string)($d['content']??''));foreach(['title','excerpt'] as $field){if(strlen(trim($d[$field]??''))<3){http_response_code(422);exit(json_encode(['error'=>"$field is required."]));}}if(strlen(trim(strip_tags($content)))<3){http_response_code(422);exit(json_encode(['error'=>'content is required.']));}$slug=slugify($d['slug']??$d['title']).'-'.substr(bin2hex(random_bytes(3)),0,6);$cat=$pdo->prepare('SELECT id FROM categories WHERE name=? LIMIT 1');$cat->execute([$d['category']??'Technology']);$status=!empty($d['publish'])?'published':'draft';$q=$pdo->prepare('INSERT INTO posts(category_id,user_id,slug,title,excerpt,image_url,content,author,status,published_at) VALUES(?,?,?,?,?,?,?,?,?,IF(?="published",NOW(),NULL))');$q->execute([$cat->fetchColumn()?:null,$user['id'],$slug,trim($d['title']),trim(strip_tags($d['excerpt'])),trim($d['image_url']??''),$content,$user['name'],$status,$status]);$refresh=$status==='published'?publishedContentChanged($pdo,$config,$slug):['sitemap_updated'=>false,'deployment_queued'=>false];http_response_code(201);exit(json_encode(['ok'=>true,'slug'=>$slug,'message'=>$status==='published'?'Your post is now live.':'Your draft was submitted for editorial review.']+$refresh));}
if($_SERVER['REQUEST_METHOD']==='PUT'){$d=input();$id=(int)($d['id']??0);$content=sanitizeRichText((string)($d['content']??''));if(!$id||strlen(trim($d['title']??''))<3||strlen(trim($d['excerpt']??''))<3||strlen(trim(strip_tags($content)))<3){http_response_code(422);exit(json_encode(['error'=>'Title, summary and story are required.']));}$post=$pdo->prepare('SELECT slug,status FROM posts WHERE id=? AND user_id=?');$post->execute([$id,$user['id']]);$saved=$post->fetch();if(!$saved){http_response_code(404);exit(json_encode(['error'=>'Post not found.']));}$cat=$pdo->prepare('SELECT id FROM categories WHERE name=? LIMIT 1');$cat->execute([$d['category']??'Technology']);$q=$pdo->prepare('UPDATE posts SET category_id=?,title=?,excerpt=?,content=? WHERE id=? AND user_id=?');$q->execute([$cat->fetchColumn()?:null,trim($d['title']),trim(strip_tags($d['excerpt'])),$content,$id,$user['id']]);$refresh=$saved['status']==='published'?publishedContentChanged($pdo,$config,$saved['slug']):['sitemap_updated'=>false,'deployment_queued'=>false];exit(json_encode(['ok'=>true,'message'=>'Your post was updated.']+$refresh));}
if($_SERVER['REQUEST_METHOD']==='DELETE'){$id=(int)($_GET['id']??0);$post=$pdo->prepare('SELECT slug,status FROM posts WHERE id=? AND user_id=?');$post->execute([$id,$user['id']]);$owned=$post->fetch();if(!$owned){http_response_code(404);exit(json_encode(['error'=>'Post not found.']));}$q=$pdo->prepare('DELETE FROM posts WHERE id=? AND user_id=?');$q->execute([$id,$user['id']]);$refresh=$owned['status']==='published'?publishedContentChanged($pdo,$config,'deleted-'.$owned['slug']):['sitemap_updated'=>false,'deployment_queued'=>false];exit(json_encode(['ok'=>true,'message'=>'Your post was deleted.']+$refresh));}
http_response_code(405);echo json_encode(['error'=>'Method not allowed.']);
